"""Render measured judge-feedback evidence into a shareable Markdown artifact."""

from __future__ import annotations

import json

from floatwise.config import get_config


def main() -> None:
    art = get_config().artifacts_dir
    report = json.loads((art / "judge_validation.json").read_text(encoding="utf-8"))
    scale = json.loads((art / "scale_benchmark.json").read_text(encoding="utf-8"))
    lines = [
        "# Generated judge-feedback results",
        "",
        "Generated by `backend/scripts/summarize_validation.py` from JSON artifacts. Synthetic evidence only.",
        "",
        f"Calibration: {' → '.join(report['calibration_period'])}. Assessment: {' → '.join(report['assessment_period'])}.",
        "The candidate fold model differs from the submitted 2026 model; these are not revised 2026 results.",
        "",
        "## Cash-out interval calibration",
        "",
        "| Slice | Raw coverage | Calibrated coverage | Raw width (BDT) | Calibrated width (BDT) |",
        "|---|---|---|---|---|",
    ]
    for name in ("overall", "event_days", "normal_days"):
        raw, adjusted = (report["calibration"][key]["cashout"][name] for key in ("raw", "calibrated"))
        lines.append(
            f"| {name} | {raw['coverage']:.1%} | {adjusted['coverage']:.1%} | {raw['width_bdt']:,} | {adjusted['width_bdt']:,} |"
        )
    event_coverage = report["calibration"]["calibrated"]["cashout"]["event_days"]["coverage"]
    lines += [
        "",
        f"Event coverage acceptance (72–88%): **{'pass' if 0.72 <= event_coverage <= 0.88 else 'fail'}**.",
        "Candidate calibration has not been promoted. Median predictions are unchanged; interval width and planning costs must be considered.",
        "",
        "## Operational comparisons",
        "",
        "| Arm | Stockout agent-days | Trips | Mean cash (BDT) |",
        "|---|---|---|---|",
    ]
    for name, result in report["pipeline_ablations"].items():
        lines.append(
            f"| {name} | {result['stockout_agent_days']:,} | {result['rebalancing_trips']:,} | {result['avg_cash_held_bdt']:,} |"
        )
    lines += [
        "",
        "Simple forecast arms with empirical intervals are fitted on the same uncensored calibration observations.",
        "Point-only arms intentionally collapse uncertainty; compare the empirical-interval arms when judging practical incremental value.",
        "The greedy/exact difference and the full pipeline's benefit over simple uncertainty-aware forecasts may be small.",
        "",
        "## Feature removals",
        "",
        "| Removed group | Cash-out WAPE | Event WAPE |",
        "|---|---|---|",
    ]
    for name, arm in report["feature_ablations"].items():
        co = arm["metrics"]["cashout"]
        lines.append(f"| {name} | {co['overall']['wape']:.1%} | {co['event_days']['wape']:.1%} |")
    lines += [
        "",
        "## Scale computation",
        "",
        "| Replicated agents | Median 7-day inference (s) | Median planning (s) |",
        "|---|---|---|",
    ]
    for row in scale["populations"]:
        seconds = row["median_seconds"]
        lines.append(
            f"| {row['n_agents']:,} | {seconds['inference_seconds']:.2f} | {seconds['planning_seconds']:.2f} |"
        )
    lines += ["", scale["limitations"], "", "## Limits", ""]
    lines += [f"- {item}" for item in report["limitations"]]
    lines += [
        "- Censored calibration samples and shifted events limit reliability; there is no statistical coverage guarantee under temporal shift.",
        "- Adherence and churn are assumptions, not measured operational behavior.",
        "- No confidence intervals for causal business effects or production SLA are claimed.",
        "",
    ]
    path = art / "judge_validation_summary.md"
    path.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {path}")


if __name__ == "__main__":
    main()
